                                                                                                                      overflow: hidden;
                                                                                                                        display: flex;
                                                                                                                          align-items: center;
                                                                                                                            justify-content: center;
                                                                                                                            }

                                                                                                                            /* Ice highlight top-left refraction */
                                                                                                                            .cat-ice-frame::before {
                                                                                                                              content: "";
                                                                                                                                position: absolute;
                                                                                                                                  inset: 0;
                                                                                                                                    border-radius: inherit;
                                                                                                                                      background: linear-gradient(135deg,
                                                                                                                                          rgba(255,255,255,0.55) 0%,
                                                                                                                                              rgba(255,255,255,0.0) 55%);
                                                                                                                                                pointer-events: none;
                                                                                                                                                  z-index: 2;
                                                                                                                                                  }

                                                                                                                                                  /* Corner sparkle */
                                                                                                                                                  .cat-ice-frame::after {
                                                                                                                                                    content: "";
                                                                                                                                                      position: absolute;
                                                                                                                                                        top: 10px;
                                                                                                                                                          left: 12px;
                                                                                                                                                            width: 36px;
                                                                                                                                                              height: 36px;
                                                                                                                                                                background: radial-gradient(circle,
                                                                                                                                                                    rgba(255,255,255,0.9) 0%,
                                                                                                                                                                        rgba(255,255,255,0.0) 70%);
                                                                                                                                                                          pointer-events: none;
                                                                                                                                                                            z-index: 3;
                                                                                                                                                                            }

                                                                                                                                                                            /* Ambient glow behind the card (accent color) */
                                                                                                                                                                            .cat-ice-glow {
                                                                                                                                                                              position: absolute;
                                                                                                                                                                                inset: -20px;
                                                                                                                                                                                  border-radius: 40px;
                                                                                                                                                                                    background: radial-gradient(ellipse at center,
                                                                                                                                                                                        var(--card-accent, #88ccff) 0%,
                                                                                                                                                                                            transparent 70%);
                                                                                                                                                                                              opacity: 0;
                                                                                                                                                                                                transition: opacity 0.5s ease;
                                                                                                                                                                                                  z-index: 0;
                                                                                                                                                                                                    pointer-events: none;
                                                                                                                                                                                                    }

                                                                                                                                                                                                    /* Image wrapper */
                                                                                                                                                                                                    .cat-ice-img-wrap {
                                                                                                                                                                                                      position: relative;
                                                                                                                                                                                                        width: 82%;
                                                                                                                                                                                                          aspect-ratio: 1 / 1;
                                                                                                                                                                                                            display: flex;
                                                                                                                                                                                                              align-items: center;
                                                                                                                                                                                                                justify-content: center;
                                                                                                                                                                                                                  z-index: 1;
                                                                                                                                                                                                                  }

                                                                                                                                                                                                                  /* Product image */
                                                                                                                                                                                                                  .cat-ice-img {
                                                                                                                                                                                                                    display: block;
                                                                                                                                                                                                                      width: 100%;
                                                                                                                                                                                                                        height: 100%;
                                                                                                                                                                                                                          object-fit: contain;
                                                                                                                                                                                                                            transition: filter 0.5s ease, transform 0.45s ease;
                                                                                                                                                                                                                              filter: drop-shadow(0 12px 20px rgba(0,0,0,0.18))
                                                                                                                                                                                                                                        drop-shadow(0 4px 8px rgba(0,0,0,0.1));
                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                        /* Shadow ellipse under product */
                                                                                                                                                                                                                                        .cat-ice-img-shadow {
                                                                                                                                                                                                                                          position: absolute;
                                                                                                                                                                                                                                            bottom: -4px;
                                                                                                                                                                                                                                              left: 50%;
                                                                                                                                                                                                                                                transform: translateX(-50%) scaleX(0.75) scaleY(0.3);
                                                                                                                                                                                                                                                  width: 70%;
                                                                                                                                                                                                                                                    height: 28px;
                                                                                                                                                                                                                                                      background: radial-gradient(ellipse at center,
                                                                                                                                                                                                                                                          rgba(60,80,120,0.35) 0%,
                                                                                                                                                                                                                                                              transparent 70%);
                                                                                                                                                                                                                                                                filter: blur(6px);
                                                                                                                                                                                                                                                                  border-radius: 50%;
                                                                                                                                                                                                                                                                    transition: transform 0.45s ease, opacity 0.45s ease, width 0.45s ease;
                                                                                                                                                                                                                                                                      z-index: 0;
                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                      /* Light emission from product onto background */
                                                                                                                                                                                                                                                                      .cat-ice-light-emit {
                                                                                                                                                                                                                                                                        position: absolute;
                                                                                                                                                                                                                                                                          inset: 10px;
                                                                                                                                                                                                                                                                            border-radius: 50%;
                                                                                                                                                                                                                                                                              background: radial-gradient(circle,
                                                                                                                                                                                                                                                                                  var(--card-accent, rgba(255,255,255,0.3)) 0%,
                                                                                                                                                                                                                                                                                      transparent 68%);
                                                                                                                                                                                                                                                                                        opacity: 0.18;
                                                                                                                                                                                                                                                                                          transition: opacity 0.5s ease;
                                                                                                                                                                                                                                                                                            pointer-events: none;
                                                                                                                                                                                                                                                                                              z-index: 0;
                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                              /* Card label */
                                                                                                                                                                                                                                                                                              .cat-ice-label {
                                                                                                                                                                                                                                                                                                margin-top: 14px;
                                                                                                                                                                                                                                                                                                  font-size: 13px;
                                                                                                                                                                                                                                                                                                    font-weight: 800;
                                                                                                                                                                                                                                                                                                      letter-spacing: 0.12em;
                                                                                                                                                                                                                                                                                                        text-transform: uppercase;
                                                                                                                                                                                                                                                                                                          color: #2d3a4a;
                                                                                                                                                                                                                                                                                                            text-align: center;
                                                                                                                                                                                                                                                                                                              transition: color 0.4s, transform 0.45s cubic-bezier(0.34,1.56,0.64,1);
                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                              /* Card description */
                                                                                                                                                                                                                                                                                                              .cat-ice-desc {
                                                                                                                                                                                                                                                                                                                margin-top: 4px;
                                                                                                                                                                                                                                                                                                                  font-size: 11.5px;
                                                                                                                                                                                                                                                                                                                    color: #7a8fa6;
                                                                                                                                                                                                                                                                                                                      text-align: center;
                                                                                                                                                                                                                                                                                                                        letter-spacing: 0.03em;
                                                                                                                                                                                                                                                                                                                          transition: color 0.4s, transform 0.45s cubic-bezier(0.34,1.56,0.64,1);
                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                          /* ─── HOVER SYSTEM (mouse/trackpad only) ─── */
@media (hover: hover) and (pointer: fine) {
  .cat-ice-grid.cat-ice-active .cat-ice-card {
    filter: brightness(0.52) saturate(0.7);
  }
  .cat-ice-grid.cat-ice-active .cat-ice-card.cat-ice-on {
    filter: brightness(1.18) saturate(1.2) !important;
    transform: translateY(-14px) !important;
    animation: none !important;
  }
  .cat-ice-card.cat-ice-on .cat-ice-glow { opacity: 0.5; }
  .cat-ice-card.cat-ice-on .cat-ice-img-shadow {
    transform: translateX(-50%) scaleX(0.45) scaleY(0.18);
