    padding: 3px 8px;
  }
}

/* =============================================
   PRODUCT DESCRIPTION CARD
   ============================================= */
.product-desc-card {
  max-width: 1200px;
  margin: 3rem auto 2rem;
  padding: 0 1.5rem;
}

.product-desc-card__label {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #ff42a1;
  margin-bottom: 0.75rem;
}
.product-desc-card__label::before {
  content: '';
  display: inline-block;
  width: 28px;
  height: 3px;
  background: #ff42a1;
  border-radius: 2px;
}

.product-desc-card__body {
  background: #fff;
  border-radius: 1.25rem;
  border: 2px solid hsl(var(--border));
  box-shadow: 0 4px 24px rgba(0,0,0,0.05);
  padding: 2.5rem 3rem;
  font-size: 17px;
  line-height: 1.9;
  color: #333;
  position: relative;
  overflow: hidden;
}
.product-desc-card__body::before {
  content: '';
  position: absolute;
  top: 0; left: 0;
  width: 5px;
  height: 100%;
  background: linear-gradient(180deg, #ff42a1, hsl(var(--secondary)));
  border-radius: 4px 0 0 4px;
}

/* Headings */
.product-desc-card__body h2,
.product-desc-card__body h3 {
  font-size: 1.3rem;
  font-weight: 800;
  color: #ff42a1;
  margin: 2rem 0 0.6rem;
  letter-spacing: 0.01em;
}
.product-desc-card__body h2:first-child,
.product-desc-card__body h3:first-child {
  margin-top: 0;
}

/* Paragraphs */
.product-desc-card__body p {
  margin-bottom: 1.1rem;
}
.product-desc-card__body p:last-child {
  margin-bottom: 0;
}

/* Lists — custom pink bullet */
.product-desc-card__body ul {
  list-style: none;
  padding: 0;
  margin: 1rem 0;
}
.product-desc-card__body ul li {
  padding-left: 1.5rem;
  position: relative;
  margin-bottom: 0.55rem;
  line-height: 1.7;
}
.product-desc-card__body ul li::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0.55em;
  width: 8px;
  height: 8px;
  background: #ff42a1;
  border-radius: 50%;
}

.product-desc-card__body strong {
  font-weight: 700;
  color: #111;
}

@media (max-width: 767px) {
  .product-desc-card { padding: 0 0.75rem; margin-top: 2rem; }
  .product-desc-card__body { padding: 1.5rem 1.25rem; font-size: 15px; }
  .product-desc-card__body h2,
  .product-desc-card__body h3 { font-size: 1.1rem; }
}

